input.command:
for r in actions/checkout astral-sh/setup-uv github/codeql-action; do echo "=== $r"; echo "latest -> $(curl -sS -o /dev/null -w '%{redirect_url}' https://github.com/$r/releases/latest)"; echo "-- feed"; curl -sS "https://github.com/$r/releases.atom" | python3 -I -c '
import sys,xml.etree.ElementTree as E
n={"a":"http://www.w3.org/2005/Atom"}
for e in E.fromstring(sys.stdin.read()).findall("a:entry",n): print(e.find("a:id",n).text.split("/")[-1], e.find("a:updated",n).text)
'; echo "-- tags"; git ls-remote --tags https://github.com/$r.git | grep -E 'refs/tags/v[0-9]+(\.[0-9]+\.[0-9]+)?(\^\{\})?$' | sort -k2 -V | tail -n 14; done

